import{_ as e,o,c as l,a5 as i}from"./chunks/framework.Bkm3ODFN.js";const q=JSON.parse('{"title":"❓ 常见排错指南 (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/faq.md","filePath":"deploy/faq.md","lastUpdated":1794271174000}'),t={name:"deploy/faq.md"};function r(d,a,n,s,c,h){return o(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="❓-常见排错指南-faq" tabindex="-1">❓ 常见排错指南 (FAQ) <a class="header-anchor" href="#❓-常见排错指南-faq" aria-label="Permalink to &quot;❓ 常见排错指南 (FAQ)&quot;">​</a></h1><p>本文档整理了 MzMedia 在实际生产与研发部署过程中最常见的故障现象及排查手段。</p><hr><h2 id="_1-视频与流媒体常见问题" tabindex="-1">1. 视频与流媒体常见问题 <a class="header-anchor" href="#_1-视频与流媒体常见问题" aria-label="Permalink to &quot;1. 视频与流媒体常见问题&quot;">​</a></h2><h3 id="q1-摄像头在海康-大华后台配置后-平台显示注册成功-但点击播放提示超时或黑屏" tabindex="-1">Q1: 摄像头在海康/大华后台配置后，平台显示注册成功，但点击播放提示超时或黑屏？ <a class="header-anchor" href="#q1-摄像头在海康-大华后台配置后-平台显示注册成功-但点击播放提示超时或黑屏" aria-label="Permalink to &quot;Q1: 摄像头在海康/大华后台配置后，平台显示注册成功，但点击播放提示超时或黑屏？&quot;">​</a></h3><ul><li><strong>排查步骤</strong>： <ol><li>检查 <code>application.yaml</code> 中的 <code>sip.ip</code> 与 <code>media.ip</code>，<strong>严禁配置为 <code>127.0.0.1</code></strong>，必须配置为摄像头在局域网内或公网能直接路由访问的实际 IP 地址；</li><li>检查宿主机防火墙是否阻断了 ZLMediaKit 的动态 RTP 端口（默认 <code>30000-30500</code>）；</li><li>检查摄像机视频编码格式，部分老设备默认推复合流或 H.265，如果浏览器不支持硬解，可在平台点播设置中勾选转码为 H.264。</li></ol></li></ul><h3 id="q2-摄像机在线-但是获取不到通道列表或目录为空" tabindex="-1">Q2: 摄像机在线，但是获取不到通道列表或目录为空？ <a class="header-anchor" href="#q2-摄像机在线-但是获取不到通道列表或目录为空" aria-label="Permalink to &quot;Q2: 摄像机在线，但是获取不到通道列表或目录为空？&quot;">​</a></h3><ul><li><strong>排查步骤</strong>： <ol><li>检查摄像机配置的 SIP 服务器 ID（国标 20 位）与平台配置是否完全一致；</li><li>检查大包分包：当设备下挂通道较多时，XML 报文可能超过单包 MTU 导致 UDP 丢包，建议在前端将该设备的 SIP 传输协议切换为 <strong>TCP</strong> 模式。</li></ol></li></ul><hr><h2 id="_2-物联网与工控通信常见问题" tabindex="-1">2. 物联网与工控通信常见问题 <a class="header-anchor" href="#_2-物联网与工控通信常见问题" aria-label="Permalink to &quot;2. 物联网与工控通信常见问题&quot;">​</a></h2><h3 id="q1-modbus-读取到的数值为负数、极大极小值或与现场仪表显示不符" tabindex="-1">Q1: Modbus 读取到的数值为负数、极大极小值或与现场仪表显示不符？ <a class="header-anchor" href="#q1-modbus-读取到的数值为负数、极大极小值或与现场仪表显示不符" aria-label="Permalink to &quot;Q1: Modbus 读取到的数值为负数、极大极小值或与现场仪表显示不符？&quot;">​</a></h3><ul><li><strong>排查步骤</strong>： <ol><li>检查<strong>字节序 (Endianness)</strong> 设置：常规使用大端（ABCD），施耐德等常见字交换（CDAB），国产仪器仪表常见字节交换（BADC）；</li><li>检查<strong>寄存器起始地址基准</strong>：查看设备手册标注的是 0 开始（0-based）还是 1 开始（1-based），若存在 1 的偏移，需在配置中相应加减 1；</li><li>检查<strong>缩放系数 (Scale)</strong>：确认浮点数是否需要乘以 0.1 或 0.01 转换。</li></ol></li></ul><h3 id="q2-设备连接-mqtt-broker-频繁掉线" tabindex="-1">Q2: 设备连接 MQTT Broker 频繁掉线？ <a class="header-anchor" href="#q2-设备连接-mqtt-broker-频繁掉线" aria-label="Permalink to &quot;Q2: 设备连接 MQTT Broker 频繁掉线？&quot;">​</a></h3><ul><li><strong>排查步骤</strong>： <ol><li>检查每个物理设备的 <code>ClientID</code> 是否全球唯一，禁止两台物理设备使用同一个 ClientID 连接，否则会发生互相踢线（KeepAlive 争抢）；</li><li>检查心跳间隔（KeepAlive），建议设置为 60 秒并开启客户端断线自动重连。</li></ol></li></ul><hr><h2 id="_3-spring-ai-与-mcp-智能体常见问题" tabindex="-1">3. Spring AI 与 MCP 智能体常见问题 <a class="header-anchor" href="#_3-spring-ai-与-mcp-智能体常见问题" aria-label="Permalink to &quot;3. Spring AI 与 MCP 智能体常见问题&quot;">​</a></h2><h3 id="q1-启动时报错-chatclient-builder-重复注入或找不到-bean" tabindex="-1">Q1: 启动时报错 <code>ChatClient.Builder</code> 重复注入或找不到 Bean？ <a class="header-anchor" href="#q1-启动时报错-chatclient-builder-重复注入或找不到-bean" aria-label="Permalink to &quot;Q1: 启动时报错 `ChatClient.Builder` 重复注入或找不到 Bean？&quot;">​</a></h3><ul><li><strong>排查步骤</strong>： <ul><li>项目设计了多模型动态工厂 <code>Ai1LlmModelFactory</code>。请确保 <code>application.yaml</code> 中配置了 <code>spring.ai.chat.client.enabled: false</code>，避免 Spring Boot 官方自动装配单一固定 Client 产生冲突。</li></ul></li></ul><h3 id="q2-本地-stdio-mcp-客户端启动失败或报找不到命令" tabindex="-1">Q2: 本地 stdio MCP 客户端启动失败或报找不到命令？ <a class="header-anchor" href="#q2-本地-stdio-mcp-客户端启动失败或报找不到命令" aria-label="Permalink to &quot;Q2: 本地 stdio MCP 客户端启动失败或报找不到命令？&quot;">​</a></h3><ul><li><strong>排查步骤</strong>： <ul><li>确认 MCP 配置中填写的命令行程序（如 <code>python</code>、<code>node</code>、<code>uvx</code>）已加入操作系统的系统环境变量 <code>PATH</code> 中；</li><li>检查当前执行账户是否具备对应脚本文件与工作目录的读写执行权限。</li></ul></li></ul>',20)])])}const p=e(t,[["render",r]]);export{q as __pageData,p as default};
